import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        char bestChar = 0;
        int bestLen = 0;
        for (int i = 0; i < s.length();) {
            int j = i + 1;
            while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
            // ">=" keeps the rightmost run on ties.
            if (j - i >= bestLen) { bestLen = j - i; bestChar = s.charAt(i); }
            i = j;
        }
        System.out.println("" + bestChar + bestLen);
    }
}

